return ['messages'=>['0e747ff8b1ac4477d92045e85c49b1be'=>'Jimmy Solano, <em>Commercial Head</em> da Centroamérica.','14dee4ddd3a44872d05b1c4e85609379'=>'<span class="TextRun SCXW204204079 BCX0" lang="PT-BR" xml:lang="PT-BR" data-contrast="none"><span class="NormalTextRun SCXW204204079 BCX0">Com uma sólida trajetória de compromisso com o desenvolvimento local, a </span><a href="https://www.coopesanramon.fi.cr/" target="_blank" rel="noopener"><span class="NormalTextRun SpellingErrorV2Themed SCXW204204079 BCX0">Coopesanramón</span></a><span class="NormalTextRun SCXW204204079 BCX0"> se junta às instituições financeiras que estão transformando a experiência de seus associados por meio de soluções digitais acessíveis e sustentáveis.</span></span><span class="EOP SCXW204204079 BCX0" data-ccp-props="{&quot;335551550&quot;:6,&quot;335551620&quot;:6}"> </span>','2e804d96f7b939d21bb11946a47e30c5'=>'Parabenizamos a Coopesanramón por esta importante conquista e por continuar implementando iniciativas que transformam a experiência de seus associados e fortalecem sua posição no mercado financeiro. ','6392ee3a9e9b8f91a9416880fa2a20f8'=>'Para a Evertec, o Zunify é uma plataforma fundamental para fortalecer o ecossistema de pagamentos na Costa Rica, impulsionando as transações nos comércios e oferecendo aos usuários múltiplos benefícios. Ser o parceiro tecnológico da Coopesanramón neste projeto nos permite cumprir nosso compromisso de oferecer soluções que evoluem com as necessidades do mercado, apoiando sua missão de oferecer serviços confiáveis por meio de tecnologia de ponta que facilita transações rápidas, seguras e com valor agregado.','Con una sólida trayectoria de compromiso con el desarrollo local, <a href="https://www.coopesanramon.fi.cr/" target="_blank" rel="noreferrer noopener">Coopesanramón</a> se suma a las entidades financieras que están transformando la experiencia de sus asociados mediante soluciones digitales accesibles y sostenibles. '=>'<span class="TextRun SCXW204204079 BCX0" lang="PT-BR" xml:lang="PT-BR" data-contrast="none"><span class="NormalTextRun SCXW204204079 BCX0">Com uma sólida trajetória de compromisso com o desenvolvimento local, a </span><a href="https://www.coopesanramon.fi.cr/" target="_blank" rel="noopener"><span class="NormalTextRun SpellingErrorV2Themed SCXW204204079 BCX0">Coopesanramón</span></a><span class="NormalTextRun SCXW204204079 BCX0"> se junta às instituições financeiras que estão transformando a experiência de seus associados por meio de soluções digitais acessíveis e sustentáveis.</span></span><span class="EOP SCXW204204079 BCX0" data-ccp-props="{&quot;335551550&quot;:6,&quot;335551620&quot;:6}"> </span>','Felicitamos a Coopesanramón por este importante logro y por seguir implementando iniciativas que transforman la experiencia de sus asociados y fortalecen su posición en el mercado financiero. '=>'Parabenizamos a Coopesanramón por esta importante conquista e por continuar implementando iniciativas que transformam a experiência de seus associados e fortalecem sua posição no mercado financeiro. ','Jimmy Solano, <em>Commercial Head</em> de Centroamérica.'=>'Jimmy Solano, <em>Commercial Head</em> da Centroamérica.','La cooperativa ha dado un paso clave en su evolución tecnológica al implementar Zunify, la red de <a href="/solucion/pagos-con-billetera-digital-y-codigo-qr/">pagos QR de Evertec</a> que unifica el sistema financiero en una sola aplicación. Esta innovación les permite a los clientes de la cooperativa centralizar la gestión de sus cuentas de débito, realizar pagos con códigos QR, acumular <em>cashback</em>, aplicar descuentos y promociones en comercios afiliados, y realizar pagos remotos mediante la funcionalidad Notify.'=>'<span class="TextRun SCXW43613663 BCX0" lang="PT-BR" xml:lang="PT-BR" data-contrast="none"><span class="NormalTextRun SCXW43613663 BCX0">A cooperativa deu um passo fundamental em sua evolução tecnológica ao implementar o </span></span><span class="TextRun MacChromeBold SCXW43613663 BCX0" lang="PT-BR" xml:lang="PT-BR" data-contrast="none"><span class="NormalTextRun SpellingErrorV2Themed SCXW43613663 BCX0">Zunify</span></span><span class="TextRun SCXW43613663 BCX0" lang="PT-BR" xml:lang="PT-BR" data-contrast="none"><span class="NormalTextRun SCXW43613663 BCX0">, a rede de <a href="/pt-br/solucao/pagamentos-com-carteira-digital-e-qr-code/">pagamentos </a></span><span class="NormalTextRun SCXW43613663 BCX0">via</span><span class="NormalTextRun SCXW43613663 BCX0"> QR </span><span class="NormalTextRun SpellingErrorV2Themed SCXW43613663 BCX0">Code</span> <span class="NormalTextRun SCXW43613663 BCX0">da </span><span class="NormalTextRun SpellingErrorV2Themed SCXW43613663 BCX0">Evertec</span><span class="NormalTextRun SCXW43613663 BCX0"> que unifica o sistema financeiro em um único aplicativo. Essa inovação permite que os clientes da cooperativa centralizem a gestão de suas contas </span><span class="NormalTextRun SCXW43613663 BCX0">e cartões</span> <span class="NormalTextRun SCXW43613663 BCX0">de débito, realizem pagamentos com QR </span><span class="NormalTextRun SpellingErrorV2Themed SCXW43613663 BCX0">code</span><span class="NormalTextRun SCXW43613663 BCX0">, acumulem </span><span class="NormalTextRun SpellingErrorV2Themed SCXW43613663 BCX0">cashback</span><span class="NormalTextRun SCXW43613663 BCX0">, aproveitem descontos e promoções em estabelecimentos afiliados e efetuem pagamentos remotos por meio da funcionalidade </span><span class="NormalTextRun SpellingErrorV2Themed SpellingErrorHighlight SCXW43613663 BCX0">Notify</span><span class="NormalTextRun SCXW43613663 BCX0">.</span></span><span class="EOP SCXW43613663 BCX0" data-ccp-props="{&quot;335551550&quot;:6,&quot;335551620&quot;:6}"> </span>','Para Evertec, Zunify es una plataforma clave para fortalecer el ecosistema de pagos en Costa Rica, impulsando las transacciones en comercios y ofreciendo a los usuarios múltiples beneficios. Ser el socio tecnológico de Coopesanramón en este proyecto nos permite cumplir nuestro compromiso de brindar soluciones que evolucionen con las necesidades del mercado, apoyando su misión de ofrecer servicios confiables mediante tecnología de vanguardia que facilita transacciones rápidas, seguras y con valor agregado. '=>'Para a Evertec, o Zunify é uma plataforma fundamental para fortalecer o ecossistema de pagamentos na Costa Rica, impulsionando as transações nos comércios e oferecendo aos usuários múltiplos benefícios. Ser o parceiro tecnológico da Coopesanramón neste projeto nos permite cumprir nosso compromisso de oferecer soluções que evoluem com as necessidades do mercado, apoiando sua missão de oferecer serviços confiáveis por meio de tecnologia de ponta que facilita transações rápidas, seguras e com valor agregado.','df573ef0462c63990f6e7fc1d68f836e'=>'<span class="TextRun SCXW43613663 BCX0" lang="PT-BR" xml:lang="PT-BR" data-contrast="none"><span class="NormalTextRun SCXW43613663 BCX0">A cooperativa deu um passo fundamental em sua evolução tecnológica ao implementar o </span></span><span class="TextRun MacChromeBold SCXW43613663 BCX0" lang="PT-BR" xml:lang="PT-BR" data-contrast="none"><span class="NormalTextRun SpellingErrorV2Themed SCXW43613663 BCX0">Zunify</span></span><span class="TextRun SCXW43613663 BCX0" lang="PT-BR" xml:lang="PT-BR" data-contrast="none"><span class="NormalTextRun SCXW43613663 BCX0">, a rede de <a href="/pt-br/solucao/pagamentos-com-carteira-digital-e-qr-code/">pagamentos </a></span><span class="NormalTextRun SCXW43613663 BCX0">via</span><span class="NormalTextRun SCXW43613663 BCX0"> QR </span><span class="NormalTextRun SpellingErrorV2Themed SCXW43613663 BCX0">Code</span> <span class="NormalTextRun SCXW43613663 BCX0">da </span><span class="NormalTextRun SpellingErrorV2Themed SCXW43613663 BCX0">Evertec</span><span class="NormalTextRun SCXW43613663 BCX0"> que unifica o sistema financeiro em um único aplicativo. Essa inovação permite que os clientes da cooperativa centralizem a gestão de suas contas </span><span class="NormalTextRun SCXW43613663 BCX0">e cartões</span> <span class="NormalTextRun SCXW43613663 BCX0">de débito, realizem pagamentos com QR </span><span class="NormalTextRun SpellingErrorV2Themed SCXW43613663 BCX0">code</span><span class="NormalTextRun SCXW43613663 BCX0">, acumulem </span><span class="NormalTextRun SpellingErrorV2Themed SCXW43613663 BCX0">cashback</span><span class="NormalTextRun SCXW43613663 BCX0">, aproveitem descontos e promoções em estabelecimentos afiliados e efetuem pagamentos remotos por meio da funcionalidade </span><span class="NormalTextRun SpellingErrorV2Themed SpellingErrorHighlight SCXW43613663 BCX0">Notify</span><span class="NormalTextRun SCXW43613663 BCX0">.</span></span><span class="EOP SCXW43613663 BCX0" data-ccp-props="{&quot;335551550&quot;:6,&quot;335551620&quot;:6}"> </span>']];
